class HistoricalProgram:
    def __init__(self, value):self.value=value
    def source(self, correlation):return self.value


@unittest.skipUnless(os.name=='posix','actual descriptor/process shell transport requires POSIX')
class NativeAbiCausalTest(unittest.TestCase):
    def boot(self, raw):return next(x[5:]for x in raw.splitlines()if x.startswith('BOOT '))

    def test_missing_separate_mksh_actual_old_failure_then_fixed_whole_program(self):
        old,corr,left,seams=run(HistoricalProgram(_OLD_MISSING_SHELL))
        self.assertNotEqual(old.returncode,0);self.assertIn(b'guest-mksh',old.stderr);self.assertNotIn(b'PHYSICAL-READONLY-4',old.stdout);self.assertEqual(left,[])
        child,corr,left,seams=run(abi);self.assertEqual(child.returncode,0,child.stderr);self.assertEqual(left,[])
        facts=abi.parse(child.stdout.decode(),corr,self.boot(child.stdout.decode()))
        self.assertEqual(facts['shellPath'],'/system/bin/sh');self.assertEqual(facts['profileVersion'],4);self.assertFalse(facts['batchEnabled'])

    @unittest.skipIf(hasattr(os,'geteuid')and os.geteuid()==0,'actual DAC denied open requires nonroot principal')
    def test_denied_regular_file_actual_old_failure_then_verified_utility(self):
        old,corr,left,seams=run(HistoricalProgram(_OLD_DENIED_FILE),deny_build_prop=True)
        self.assertNotEqual(old.returncode,0);self.assertIn(b'Permission denied',old.stderr);self.assertIn(b'TOYBOX-HASH ',old.stdout);self.assertNotIn(b'FD4 ',old.stdout);self.assertEqual(left,[])
        child,corr,left,seams=run(abi,deny_build_prop=True);self.assertEqual(child.returncode,0,child.stderr);raw=child.stdout.decode();facts=abi.parse(raw,corr,self.boot(raw))
        self.assertEqual(facts['fdSha256'],facts['toyboxSha256']);self.assertEqual(left,[])

    def test_real_sigkill_status137_actual_old_failure_then_owned_child_proof(self):
        old,corr,left,seams=run(HistoricalProgram(_OLD_STATUS124))
        self.assertEqual(old.returncode,95);self.assertEqual(old.stdout.splitlines()[-1],b'WATCHDOG 137');self.assertNotIn(b'LIMIT-PROOF ',old.stdout)
        proof=seams['watchdogEvidence'];self.assertEqual(proof['waitReturnCode'],-9);self.assertTrue(proof['heldChildReaped']);self.assertTrue(proof['timedOut'])
        child,corr,left,seams=run(abi);self.assertEqual(child.returncode,0,child.stderr);raw=child.stdout.decode();facts=abi.parse(raw,corr,self.boot(raw))
        self.assertEqual(facts['watchdogExit'],137);self.assertEqual(facts['watchdogChildPid'],seams['watchdogEvidence']['pid']);self.assertTrue(facts['watchdogChildAbsent']);self.assertEqual(facts['fileLimit'],16384)

    def test_actual_source_child_identity_permission_limit_and_closing_fail_closed(self):
        for drift in ('status124','no-child','birth','post-permission','limit','utility','mapping'):
            with self.subTest(drift=drift):
                child,corr,left,seams=run(abi,drift);self.assertNotEqual(child.returncode,0);self.assertEqual(left,[]);self.assertNotIn(b'EOF READONLY-4 COMPLETE',child.stdout)
                with self.assertRaises(ValueError):abi.parse(child.stdout.decode(),corr,self.boot(child.stdout.decode()))


def canonical_reply(correlation,boot):
    generation='1:2:81ed:0:2000:1:128:fixed-time:fixed-ctime'
    sha='a'*64
    return '\n'.join(['PHYSICAL-READONLY-4','UID 2000','SHELL /system/bin/sh','UTILITY /system/bin/toybox','NAMED-SH-GENERATION '+generation,'SH-KIND regular','SH-TARGET NONE','KSH-VERSION '+base64.b64encode(b'@(#)MIRBSD KSH R59 Android').decode(),'PRINCIPAL uid=2000(shell) gid=2000(shell) groups=2000(shell)','BOOT '+boot,'INHERITED-LIMITS '+base64.b64encode(b'Max file size unlimited unlimited bytes\n').decode(),'SHELL-GENERATION '+generation,'TOYBOX-GENERATION '+generation,'SHELL-HASH '+sha+'  /system/bin/sh','TOYBOX-HASH '+sha+'  /system/bin/toybox','FD4 '+sha,'FD5 '+sha,'WATCHDOG-CHILD '+correlation+' 123 456 2000','WATCHDOG 137','WATCHDOG-TIME 100.00 101.00','WATCHDOG-POST 1 '+base64.b64encode(b"stat: '/proc/123': No such file or directory").decode(),'LIMIT-PROOF '+base64.b64encode(b'Max file size 16384 16384 bytes').decode(),'EOF READONLY-4 COMPLETE'])+'\n'


class PortableParserTest(unittest.TestCase):
    def test_positive_has_no_native_owner_sink_runtime_or_batch_authority(self):
        corr,boot=str(uuid.uuid4()),str(uuid.uuid4());facts=abi.parse(canonical_reply(corr,boot),corr,boot)
        for key in ('nativeAcceptance','ownerAdmission','runtimeAdmission','batchEnabled','overflowWriteProven'):self.assertIs(facts[key],False)

    def test_strict_child_elapsed_permission_kernel_and_partial_refusals(self):
        corr,boot=str(uuid.uuid4()),str(uuid.uuid4());raw=canonical_reply(corr,boot)
        bad=[raw.replace('WATCHDOG 137','WATCHDOG 124'),raw.replace('100.00 101.00','100.00 102.00'),raw.replace('100.00 101.00','101.00 100.00'),raw.replace(corr+' 123 456 2000',str(uuid.uuid4())+' 123 456 2000'),raw.replace('123 456 2000','123 456 0'),raw.replace('123 456 2000','123 1.0 2000'),raw.replace('WATCHDOG-POST 1 ','WATCHDOG-POST 0 '),raw.replace(base64.b64encode(b"stat: '/proc/123': No such file or directory").decode(),base64.b64encode(b"stat: '/proc/123': Permission denied").decode()),raw.replace('FD5 '+'a'*64,'FD5 '+'b'*64),raw.replace(base64.b64encode(b'Max file size 16384 16384 bytes').decode(),base64.b64encode(b'Max file size 32768 32768 bytes').decode()),raw.rstrip(),raw+'extra\n',raw.replace('EOF READONLY-4 COMPLETE',''),raw.replace('UID 2000','UID 0'),raw.replace('SHELL /system/bin/sh','SHELL /outside/sh')]
        for value in bad:
            with self.subTest(value=value[-120:]):
                with self.assertRaises(ValueError):abi.parse(value,corr,boot)
        with self.assertRaises(ValueError):abi.parse(raw,corr,str(uuid.uuid4()))
        for badcorr in (True,1.0,None,'not-uuid'):
            with self.assertRaises(ValueError):abi.parse(raw,badcorr,boot)
            with self.assertRaises((ValueError,TypeError)):abi.source(badcorr)

if __name__=='__main__':unittest.main()
